--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `orders` (
  `order_id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `status` varchar(50) DEFAULT 'Pending',
  `total_price` decimal(10,2) DEFAULT 0.00,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `shop_id` int(11) DEFAULT NULL,
  `rider_latitude` decimal(10,8) DEFAULT NULL,
  `rider_longitude` decimal(11,8) DEFAULT NULL,
  `rider_id` int(11) DEFAULT NULL,
  `payment_method` varchar(50) DEFAULT 'Cash on Delivery',
  `arrived_notified_at` datetime DEFAULT NULL,
  `id` int(11) GENERATED ALWAYS AS (`order_id`) VIRTUAL,
  `customer_id` int(11) GENERATED ALWAYS AS (`user_id`) VIRTUAL,
  `acknowledged_seen` tinyint(1) DEFAULT 0,
  `rider_cleared` tinyint(1) DEFAULT 0,
  `payment_status` varchar(50) DEFAULT 'unpaid',
  `order_status` varchar(50) DEFAULT 'placed',
  `delivery_address` text DEFAULT NULL,
  `delivery_lat` decimal(10,8) DEFAULT NULL,
  `delivery_lng` decimal(11,8) DEFAULT NULL,
  `order_number` varchar(50) DEFAULT NULL,
  `delivered_at` datetime DEFAULT NULL,
  `awaiting_settlement` tinyint(1) NOT NULL DEFAULT 0,
  `store_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `items_summary` text DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `customer_phone` varchar(30) DEFAULT NULL,
  `store_id` int(11) DEFAULT NULL,
  `current_lat` decimal(10,8) DEFAULT NULL,
  `current_lng` decimal(11,8) DEFAULT NULL,
  `store_lat` decimal(10,7) DEFAULT 11.0065000,
  `store_lng` decimal(10,7) DEFAULT 124.6075000,
  `rider_name` varchar(150) DEFAULT NULL,
  `rider_phone` varchar(50) DEFAULT NULL,
  `rider_lat` decimal(10,7) DEFAULT NULL,
  `rider_lng` decimal(10,7) DEFAULT NULL,
  `total_amount` decimal(10,2) NOT NULL DEFAULT 0.00,
  PRIMARY KEY (`order_id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `orders_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=8153 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

